type SignedTxHash = HashOf<iroha_data_model::transaction::SignedTransaction>;
type QueuePlanJournalRemoval = (HashOf<TransactionEntrypoint>, Hash, Hash);

fn compatibility_queue_hash(entrypoint_hash: HashOf<TransactionEntrypoint>) -> SignedTxHash {
    HashOf::from_untyped_unchecked(Hash::from(entrypoint_hash))
}

fn exact_signed_transaction_hash(
    entrypoint: &TransactionEntrypoint,
) -> Option<HashOf<iroha_data_model::transaction::SignedTransaction>> {
    match entrypoint {
        TransactionEntrypoint::External(signed) => Some(signed.hash()),
        TransactionEntrypoint::SealedReveal(reveal) => Some(reveal.signed_transaction().hash()),
        TransactionEntrypoint::SealedCommitment(_)
        | TransactionEntrypoint::PrivateKaigi(_)
        | TransactionEntrypoint::Time(_) => None,
    }
}

/// Return the latest queued full routing plan recorded for a transaction hash.
#[must_use]
pub fn routing_plan_hint(
    hash: &HashOf<iroha_data_model::transaction::SignedTransaction>,
) -> Option<RoutingPlan> {
    routing_ledger::get_plan(hash)
}

/// Convert a queue routing plan into durable block execution-context legs.
#[must_use]
pub(crate) fn execution_context_legs_for_routing_plan(
    plan: &RoutingPlan,
) -> Vec<ExternalExecutionRouteLeg> {
    plan.legs()
        .into_iter()
        .map(|leg| {
            let role = match leg.role {
                RouteLegRole::Coordinator => ExternalExecutionRouteRole::Coordinator,
                RouteLegRole::Participant => ExternalExecutionRouteRole::Participant,
            };
            ExternalExecutionRouteLeg::new(leg.route.lane_id, leg.route.dataspace_id, role)
        })
        .collect()
}

/// Convert a queue routing plan into one durable external block execution context.
#[must_use]
pub(crate) fn execution_context_for_routing_plan(
    entrypoint_hash: HashOf<TransactionEntrypoint>,
    plan: &RoutingPlan,
) -> ExternalExecutionContext {
    let coordinator = plan.coordinator_route();
    ExternalExecutionContext::with_routing_plan(
        entrypoint_hash,
        coordinator.lane_id,
        coordinator.dataspace_id,
        plan.digest(),
        execution_context_legs_for_routing_plan(plan),
    )
}

/// Version of the queue-plan lifecycle context embedded in durable admission claims.
pub const QUEUE_PLAN_ADMISSION_CONTEXT_VERSION_V2: u16 = 2;
/// Version of a queue-plan durable admission claim returned after a strict journal sync.
pub const QUEUE_PLAN_DURABLE_ADMISSION_VERSION_V2: u16 = 2;
/// Version of the global admission identity embedded in a strict queue-plan journal record.
pub const QUEUE_PLAN_GLOBAL_ADMISSION_IDENTITY_VERSION_V2: u16 = 2;

/// Chain/request identity chosen once by ingress before any authority acquires queue ownership.
///
/// This identity is persisted inside the exact journal record. Together with the record's
/// canonical enqueue timestamp and claim digest it lets restart recovery reconstruct the same
/// global admission binding that every authority attested.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Encode, Decode)]
pub struct QueuePlanGlobalAdmissionIdentityV2 {
    /// Identity layout version.
    pub version: u16,
    /// Domain-separated digest of the chain identifier.
    pub chain_id_digest: Hash,
    /// Deterministic QueuePlanSynced proxy request identity.
    pub request_id: Hash,
}

/// One routing leg paired with the exact active lane incarnation that admitted it.
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode)]
pub struct QueuePlanRouteIncarnationV2 {
    /// Coordinator or participant route in canonical routing-plan order.
    pub leg: RouteLeg,
    /// Non-zero lane incarnation active for this route at `proposal_height`.
    pub lane_incarnation: Hash,
    /// Version of the canonical ordered validator-set hash.
    pub validator_set_hash_version: u16,
    /// Typed digest of the ordered authoritative roster at `proposal_height`.
    pub validator_set_hash: HashOf<Vec<PeerId>>,
    /// Exact ordered authoritative roster at `proposal_height`.
    pub validator_set: Vec<PeerId>,
    /// Number of distinct identities in the authoritative roster.
    pub validator_count: u16,
    /// Minimum distinct durable attestations needed to include at least one honest copy.
    pub durability_threshold: u16,
}

/// Generation-stable lifecycle context for one queue-plan admission attempt.
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode)]
pub struct QueuePlanAdmissionContextV2 {
    /// Context layout version.
    pub version: u16,
    /// Canonical committed height used to resolve the routing plan.
    pub authority_height: u64,
    /// Contiguous next proposal height at which all route incarnations are active.
    pub proposal_height: u64,
    /// Exact committed tip that is the predecessor of `proposal_height`.
    pub predecessor_block_hash: Option<HashOf<BlockHeader>>,
    /// Digest of the complete coordinator/participant routing plan.
    pub routing_plan_digest: Hash,
    /// Coordinator-first route/incarnation pairs for the complete plan.
    pub route_incarnations: Vec<QueuePlanRouteIncarnationV2>,
}

impl QueuePlanAdmissionContextV2 {
    /// Reconstruct the complete canonical routing plan carried by this context.
    ///
    /// # Errors
    /// Returns an error when the leg vector is empty or its roles/order cannot encode one
    /// canonical single-route or Native AMX plan.
    pub fn routing_plan(&self) -> Result<RoutingPlan, String> {
        let Some(coordinator) = self.route_incarnations.first() else {
            return Err("queue-plan admission context has no coordinator leg".to_owned());
        };
        if coordinator.leg.role != RouteLegRole::Coordinator {
            return Err("queue-plan admission context first leg is not the coordinator".to_owned());
        }
        if self.route_incarnations.len() == 1 {
            return Ok(RoutingPlan::single(coordinator.leg.route));
        }
        let participants = self
            .route_incarnations
            .iter()
            .skip(1)
            .map(|bound| {
                if bound.leg.role != RouteLegRole::Participant {
                    return Err(
                        "queue-plan admission context contains a non-participant trailing leg"
                            .to_owned(),
                    );
                }
                Ok(bound.leg)
            })
            .collect::<Result<Vec<_>, _>>()?;
        Ok(RoutingPlan::native_amx(coordinator.leg.route, participants))
    }

    /// Validate this context against an exact canonical routing plan.
    ///
    /// # Errors
    /// Returns the first structural, lifecycle, roster, or redundant-field mismatch.
    pub fn validate_for_routing_plan(&self, routing_plan: &RoutingPlan) -> Result<(), String> {
        let canonical_plan = match routing_plan {
            RoutingPlan::Single(leg) => RoutingPlan::single(leg.route),
            RoutingPlan::NativeAmx(plan) => {
                if plan.participants.is_empty()
                    || plan.participants.len() > crate::native_amx::MAX_NATIVE_AMX_PARTICIPANT_LEGS
                {
                    return Err(format!(
                        "queue-plan Native AMX participant count {} is outside 1..={}",
                        plan.participants.len(),
                        crate::native_amx::MAX_NATIVE_AMX_PARTICIPANT_LEGS
                    ));
                }
                RoutingPlan::native_amx(plan.coordinator.route, plan.participants.clone())
            }
        };
        if &canonical_plan != routing_plan {
            return Err(
                "queue-plan admission context is paired with a noncanonical routing plan"
                    .to_owned(),
            );
        }
        if self.version != QUEUE_PLAN_ADMISSION_CONTEXT_VERSION_V2 {
            return Err(format!(
                "unsupported queue-plan admission context version {}; expected {}",
                self.version, QUEUE_PLAN_ADMISSION_CONTEXT_VERSION_V2
            ));
        }
        let Some(expected_proposal_height) = self.authority_height.checked_add(1) else {
            return Err(
                "queue-plan admission authority height overflows proposal height".to_owned(),
            );
        };
        if self.proposal_height != expected_proposal_height {
            return Err(
                "queue-plan admission proposal height is not contiguous with authority height"
                    .to_owned(),
            );
        }
        if (self.authority_height == 0) != self.predecessor_block_hash.is_none() {
            return Err(
                "queue-plan admission predecessor hash presence does not match authority height"
                    .to_owned(),
            );
        }
        if self
            .predecessor_block_hash
            .is_some_and(|hash| hash_is_zero(Hash::from(hash)))
        {
            return Err(
                "queue-plan admission context contains a zero predecessor block hash".to_owned(),
            );
        }
        if self.routing_plan_digest != routing_plan.digest() {
            return Err(
                "queue-plan admission context digest does not match the exact routing plan"
                    .to_owned(),
            );
        }
        let legs = routing_plan.legs();
        if self.route_incarnations.len() != legs.len() {
            return Err(
                "queue-plan admission context does not bind every routing leg exactly once"
                    .to_owned(),
            );
        }
        for (bound, expected_leg) in self.route_incarnations.iter().zip(legs) {
            if bound.leg != expected_leg {
                return Err(
                    "queue-plan admission context legs are missing, reordered, or role-mismatched"
                        .to_owned(),
                );
            }
            if hash_is_zero(bound.lane_incarnation) {
                return Err(
                    "queue-plan admission context contains a zero lane incarnation".to_owned(),
                );
            }
            if bound.validator_set_hash_version
                != iroha_data_model::consensus::VALIDATOR_SET_HASH_VERSION_V1
            {
                return Err(format!(
                    "queue-plan admission validator-set hash version {} is unsupported",
                    bound.validator_set_hash_version
                ));
            }
            if hash_is_zero(Hash::from(bound.validator_set_hash)) {
                return Err(
                    "queue-plan admission context contains a zero validator-set hash".to_owned(),
                );
            }
            let validator_count = bound.validator_set.len();
            if validator_count == 0 || validator_count > MAX_LANE_CONSENSUS_VALIDATORS {
                return Err(format!(
                    "queue-plan admission validator count {} is outside 1..={MAX_LANE_CONSENSUS_VALIDATORS}",
                    validator_count
                ));
            }
            if usize::from(bound.validator_count) != validator_count {
                return Err(format!(
                    "queue-plan admission validator count {} does not equal exact roster length {validator_count}",
                    bound.validator_count
                ));
            }
            if bound.validator_set.iter().collect::<BTreeSet<_>>().len() != validator_count {
                return Err(
                    "queue-plan admission validator roster contains duplicate identities"
                        .to_owned(),
                );
            }
            if bound.validator_set_hash != HashOf::new(&bound.validator_set) {
                return Err(
                    "queue-plan admission validator-set hash does not match the exact ordered roster"
                        .to_owned(),
                );
            }
            let expected_threshold = validator_count.div_ceil(3);
            if usize::from(bound.durability_threshold) != expected_threshold {
                return Err(format!(
                    "queue-plan admission durability threshold {} does not equal ceil({validator_count}/3)",
                    bound.durability_threshold
                ));
            }
        }
        Ok(())
    }
}

/// Exact evidence returned only after the pending-plan journal Put is durably synchronized.
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode)]
pub struct QueuePlanDurableAdmissionV2 {
    /// Claim layout version.
    pub version: u16,
    /// Lifecycle context held stable across routing validation and journal synchronization.
    pub context: QueuePlanAdmissionContextV2,
    /// Global chain/request identity persisted in the record, when this admission is eligible
    /// for a globally ordered QueuePlan certificate.
    pub global_admission_identity: Option<QueuePlanGlobalAdmissionIdentityV2>,
    /// Complete routing plan persisted in the journal record.
    pub routing_plan: RoutingPlan,
    /// Typed hash of the exact transaction entrypoint persisted in the journal record.
    pub entrypoint_hash: HashOf<TransactionEntrypoint>,
    /// Real signed-transaction hash when the entrypoint contains one.
    pub signed_transaction_hash: Option<HashOf<iroha_data_model::transaction::SignedTransaction>>,
    /// Exact queue timestamp persisted in the journal record.
    pub enqueue_timestamp_ms: u64,
    /// Domain-separated digest of the canonical `QueuePlanJournalRecordV4` bytes that crossed the
    /// sync boundary.
    pub journal_record_digest: Hash,
}

/// Recompute the canonical durable journal-record digest attested by a queue admission claim.
///
/// # Errors
/// Returns a Norito encoding error when the exact record cannot be encoded.
pub fn queue_plan_journal_record_claim_digest(
    entrypoint: TransactionEntrypoint,
    routing_plan: RoutingPlan,
    admission_context: QueuePlanAdmissionContextV2,
    enqueue_timestamp_ms: u64,
    global_admission_identity: Option<QueuePlanGlobalAdmissionIdentityV2>,
) -> Result<Hash, norito::Error> {
    QueuePlanJournalRecordV4::new(
        entrypoint,
        routing_plan,
        admission_context,
        enqueue_timestamp_ms,
        global_admission_identity,
    )
    .claim_digest()
}

/// Failure to capture a bounded, authoritative queue-plan admission context.
#[derive(Clone, Debug, PartialEq, Eq, Error)]
pub enum QueuePlanAdmissionContextError {
    /// Routing plan is no longer valid for the contiguous next proposal height.
    #[error(transparent)]
    Routing(#[from] RoutingResolveError),
    /// The requested committed generation has no exact predecessor hash in the coherent view.
    #[error(
        "queue-plan admission authority height {authority_height} has no exact committed predecessor hash"
    )]
    MissingPredecessor {
        /// Committed height whose exact block hash is unavailable.
        authority_height: u64,
    },
    /// A route has no authoritative validator binding at the admission height.
    #[error(
        "lane {lane_id} dataspace {dataspace_id} has no authoritative validators at proposal height {proposal_height}"
    )]
    MissingAuthority {
        /// Lane without an authoritative roster.
        lane_id: LaneId,
        /// Dataspace bound to the lane.
        dataspace_id: DataSpaceId,
        /// Height at which authority was resolved.
        proposal_height: u64,
    },
    /// An authority source returned duplicate validator identities.
    #[error(
        "lane {lane_id} dataspace {dataspace_id} has duplicate authoritative validators at proposal height {proposal_height}"
    )]
    DuplicateAuthority {
        /// Lane with the malformed roster.
        lane_id: LaneId,
        /// Dataspace bound to the lane.
        dataspace_id: DataSpaceId,
        /// Height at which authority was resolved.
        proposal_height: u64,
    },
    /// The resolved validator roster exceeds the protocol-wide committee bound.
    #[error(
        "lane {lane_id} dataspace {dataspace_id} authority count {validator_count} exceeds the maximum {max_validator_count}"
    )]
    AuthorityBoundExceeded {
        /// Lane with the oversized roster.
        lane_id: LaneId,
        /// Dataspace bound to the lane.
        dataspace_id: DataSpaceId,
        /// Resolved roster length.
        validator_count: usize,
        /// Protocol-wide roster limit.
        max_validator_count: usize,
    },
    /// A captured or supplied context violates the canonical V2 layout.
    #[error("noncanonical queue-plan admission context: {reason}")]
    NonCanonical {
        /// Exact canonicality failure.
        reason: String,
    },
}

/// Exact lane-local proposal slot that may take ownership of queued transactions.
///
/// The two identity hashes are supplied by lane consensus: `reservation_owner_hash` identifies
/// the leader/session taking ownership, while `proposal_identity_hash` identifies the provisional
/// proposal slot before its transaction-dependent final descriptor is assembled.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Encode, Decode)]
pub struct LaneQueueReservationScopeV1 {
    /// Lane allowed to coordinate execution of selected transactions.
    pub lane_id: LaneId,
    /// Dataspace bound to the coordinator lane.
    pub dataspace_id: DataSpaceId,
    /// Exact active lane incarnation at `proposal_height`.
    pub lane_incarnation: Hash,
    /// Global proposal height used to validate lane activation and incarnation.
    pub proposal_height: u64,
    /// Lane-local block height that will own the reservation.
    pub lane_block_height: u64,
    /// Lane-local consensus view that will own the reservation.
    pub lane_block_view: u64,
    /// Stable identity of the leader/session taking queue ownership.
    pub reservation_owner_hash: Hash,
    /// Stable provisional proposal-slot identity, independent of selected transaction contents.
    pub proposal_identity_hash: Hash,
}

impl LaneQueueReservationScopeV1 {
    fn validate(self) -> Result<(), LaneQueueReservationError> {
        if self.proposal_height == 0 {
            return Err(LaneQueueReservationError::InvalidIdentity(
                "proposal height must be non-zero".to_owned(),
            ));
        }
        if self.lane_block_height == 0 {
            return Err(LaneQueueReservationError::InvalidIdentity(
                "lane block height must be non-zero".to_owned(),
            ));
        }
        if hash_is_zero(self.lane_incarnation) {
            return Err(LaneQueueReservationError::InvalidIdentity(
                "lane incarnation must be non-zero".to_owned(),
            ));
        }
        if hash_is_zero(self.reservation_owner_hash) {
            return Err(LaneQueueReservationError::InvalidIdentity(
                "reservation owner identity must be non-zero".to_owned(),
            ));
        }
        if hash_is_zero(self.proposal_identity_hash) {
            return Err(LaneQueueReservationError::InvalidIdentity(
                "proposal identity must be non-zero".to_owned(),
            ));
        }
        Ok(())
    }
}

/// Bounded FIFO search and aggregate budgets for one lane reservation attempt.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LaneQueueReservationSelectionLimits {
    /// Maximum number of complete transactions transferred to the lane.
    pub max_transactions: NonZeroUsize,
    /// Maximum number of FIFO slots inspected, including stale and ineligible entries.
    pub max_scan: NonZeroUsize,
    /// Maximum aggregate canonical encoded transaction bytes.
    pub max_encoded_bytes: NonZeroU64,
    /// Maximum aggregate proposal gas.
    pub max_gas: NonZeroU64,
}

/// Routing-plan eligibility applied by bounded autonomous lane selection.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum LaneQueueReservationRoutingMode {
    /// Accept single-route and Native AMX transactions coordinated by the requested lane.
    #[default]
    AnyCoordinatorPlan,
    /// Accept only transactions whose complete routing plan has one coordinator leg.
    SingleRouteOnly,
}

impl LaneQueueReservationRoutingMode {
    fn allows(self, plan: &RoutingPlan) -> bool {
        match self {
            Self::AnyCoordinatorPlan => true,
            Self::SingleRouteOnly => matches!(plan, RoutingPlan::Single(_)),
        }
    }
}

/// Complete exact identity of one durable lane queue reservation.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Encode, Decode)]
#[norito(deny_unknown_fields)]
pub struct LaneQueueReservationKeyV2 {
    /// Exact encoded reservation-key schema version.
    pub version: u16,
    /// Compatibility hash of the signed transaction used by queue indexes.
    pub signed_transaction_hash: HashOf<iroha_data_model::transaction::SignedTransaction>,
    /// Canonical hash of the full transaction entrypoint.
    pub entrypoint_hash: HashOf<TransactionEntrypoint>,
    /// Exact globally committed QueuePlan admission binding authorizing economic ownership.
    pub queue_plan_admission_binding_hash: Hash,
    /// Digest of the complete single-route or Native AMX routing plan.
    pub routing_plan_digest: Hash,
    /// Exact coordinator leg; participant roles are invalid for queue ownership.
    pub coordinator_leg: RouteLeg,
    /// Coordinator lane, repeated explicitly for exact lifecycle pruning.
    pub lane_id: LaneId,
    /// Coordinator dataspace, repeated explicitly for route validation.
    pub dataspace_id: DataSpaceId,
    /// Exact active lane incarnation.
    pub lane_incarnation: Hash,
    /// Global proposal height that validated the lane incarnation.
    pub proposal_height: u64,
    /// Lane-local block height that owns the transaction.
    pub lane_block_height: u64,
    /// Lane-local consensus view that owns the transaction.
    pub lane_block_view: u64,
    /// Stable identity of the leader/session taking queue ownership.
    pub reservation_owner_hash: Hash,
    /// Stable provisional proposal-slot identity.
    pub proposal_identity_hash: Hash,
}

impl LaneQueueReservationKeyV2 {
    /// Current and only accepted reservation-key schema version.
    pub const VERSION: u16 = 2;

    /// Return a digest covering every exact identity field.
    #[must_use]
    pub fn digest(&self) -> Hash {
        Hash::new(
            norito::encode_canonical(self).expect("lane queue reservation identity must encode"),
        )
    }

    /// Validate the current schema version and complete reservation identity.
    pub(crate) fn validate(&self) -> Result<(), &'static str> {
        if self.version != Self::VERSION {
            return Err("unsupported lane queue reservation key version");
        }
        if self.coordinator_leg.role != RouteLegRole::Coordinator {
            return Err("lane reservation route role is not coordinator");
        }
        if self.coordinator_leg.route.lane_id != self.lane_id
            || self.coordinator_leg.route.dataspace_id != self.dataspace_id
        {
            return Err("lane reservation coordinator route does not match its lane scope");
        }
        if self.proposal_height == 0 || self.lane_block_height == 0 {
            return Err("lane reservation heights must be non-zero");
        }
        if hash_is_zero(self.queue_plan_admission_binding_hash)
            || hash_is_zero(self.routing_plan_digest)
            || hash_is_zero(self.lane_incarnation)
            || hash_is_zero(self.reservation_owner_hash)
            || hash_is_zero(self.proposal_identity_hash)
        {
            return Err("lane reservation cryptographic identity contains a zero hash");
        }
        if self.signed_transaction_hash != compatibility_queue_hash(self.entrypoint_hash.clone()) {
            return Err(
                "lane reservation compatibility transaction hash does not match its entrypoint",
            );
        }
        Ok(())
    }
}

/// Durable, process-independent position of one transaction in queue FIFO order.
///
/// Ordinals start at one and are never reused while a transaction remains
/// tracked. The reservation journal retains this identity while the hash is
/// absent from the ordinary FIFO so later admissions cannot overtake it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Encode, Decode)]
#[norito(deny_unknown_fields)]
struct LaneQueueFifoOrderV5 {
    /// FIFO order layout version.
    version: u16,
    /// Monotonic queue admission ordinal.
    ordinal: u64,
}

impl LaneQueueFifoOrderV5 {
    fn new(ordinal: u64) -> Result<Self, LaneQueueReservationError> {
        if ordinal == 0 {
            return Err(LaneQueueReservationError::InvalidIdentity(
                "lane queue FIFO ordinal must be non-zero".to_owned(),
            ));
        }
        Ok(Self {
            version: LANE_QUEUE_RESERVATION_JOURNAL_VERSION,
            ordinal,
        })
    }

    fn validate(self) -> Result<(), &'static str> {
        if self.version != LANE_QUEUE_RESERVATION_JOURNAL_VERSION {
            return Err("unsupported lane queue FIFO order version");
        }
        if self.ordinal == 0 {
            return Err("lane queue FIFO ordinal must be non-zero");
        }
        Ok(())
    }
}

/// Durable journal payload for one live queue reservation.
///
/// Version five is the first-release layout and intentionally rejects every
/// earlier prototype. In particular, V5 binds every reservation to an exact
/// globally committed QueuePlan admission identity and persists atomic ordered
/// release batches.
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode)]
#[norito(deny_unknown_fields)]
pub(crate) struct LaneQueueReservationRecordV5 {
    /// Record format version.
    version: u16,
    /// Exact reservation identity.
    key: LaneQueueReservationKeyV2,
    /// Original queue admission timestamp retained for release ordering and pressure age.
    enqueue_timestamp_ms: u64,
    /// Original global FIFO position retained while ordinary queue ownership is absent.
    fifo_order: LaneQueueFifoOrderV5,
}

impl LaneQueueReservationRecordV5 {
    fn validate(&self) -> Result<(), &'static str> {
        if self.version != LANE_QUEUE_RESERVATION_JOURNAL_VERSION {
            return Err("unsupported lane queue reservation journal version");
        }
        self.key.validate()?;
        self.fifo_order.validate()
    }
}

/// Exact durable queue-side identity of one autonomous-slot release.
///
/// The retirement digest alone is not sufficient here: retaining the
/// consensus/lifecycle coordinates in the journal lets replay reject an ABA
/// attempt before it can touch a live reservation from a recreated lane.
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode)]
#[norito(deny_unknown_fields)]
pub(crate) struct LaneQueueReservationReleaseBarrierV3 {
    /// Reservation-journal schema version.
    pub(crate) version: u16,
    /// Chain context of the retired payload.
    pub(crate) chain_id_hash: Hash,
    /// Consensus epoch of the retired payload.
    pub(crate) epoch: u64,
    /// Exact retired coordinator lane.
    pub(crate) lane_id: LaneId,
    /// Exact retired coordinator dataspace.
    pub(crate) dataspace_id: DataSpaceId,
    /// Exact retired lane incarnation.
    pub(crate) lane_incarnation: Hash,
    /// Global proposal height bound by the payload.
    pub(crate) proposal_height: u64,
    /// Lane-local height bound by the payload.
    pub(crate) lane_block_height: u64,
    /// Lane-local view bound by the payload.
    pub(crate) lane_block_view: u64,
    /// Canonical descriptor hash of the retired proposal.
    pub(crate) origin_descriptor_hash: Hash,
    /// Canonical proposal hash of the retired proposal.
    pub(crate) origin_proposal_hash: Hash,
    /// Canonical executable-payload hash.
    pub(crate) executable_payload_hash: Hash,
    /// Digest of the exact durable Kura retirement record.
    pub(crate) retirement_hash: Hash,
    /// Original FIFO-ordered reservation identities.
    pub(crate) ordered_keys: Vec<LaneQueueReservationKeyV2>,
}

impl LaneQueueReservationReleaseBarrierV3 {
    pub(crate) const VERSION: u16 = 3;

    pub(crate) fn validate(&self) -> Result<(), &'static str> {
        if self.version != Self::VERSION {
            return Err("unsupported lane queue release barrier version");
        }
        if self.proposal_height == 0 || self.lane_block_height == 0 {
            return Err("lane queue release barrier heights must be non-zero");
        }
        if self.ordered_keys.is_empty()
            || self.ordered_keys.len() > crate::lane_consensus::MAX_LANE_EXECUTABLE_ENTRYPOINTS
        {
            return Err("lane queue release barrier reservation count is out of bounds");
        }
        if [
            self.chain_id_hash,
            self.lane_incarnation,
            self.origin_descriptor_hash,
            self.origin_proposal_hash,
            self.executable_payload_hash,
            self.retirement_hash,
        ]
        .iter()
        .any(|hash| hash_is_zero(*hash))
        {
            return Err("lane queue release barrier contains a zero identity hash");
        }
        let mut signed_hashes = BTreeSet::new();
        let mut reservation_digests = BTreeSet::new();
        for key in &self.ordered_keys {
            key.validate()?;
            if key.lane_id != self.lane_id
                || key.dataspace_id != self.dataspace_id
                || key.lane_incarnation != self.lane_incarnation
                || key.proposal_height != self.proposal_height
                || key.lane_block_height != self.lane_block_height
                || key.lane_block_view != self.lane_block_view
            {
                return Err("lane queue release barrier key does not match its exact slot");
            }
            if !signed_hashes.insert(key.signed_transaction_hash)
                || !reservation_digests.insert(key.digest())
            {
                return Err("lane queue release barrier contains duplicate reservations");
            }
        }
        Ok(())
    }

    /// Domain-separated identity covering the complete release binding and
    /// its exact FIFO order.
    #[must_use]
    pub(crate) fn digest(&self) -> Hash {
        Hash::new_from_chunks(&[
            b"iroha:queue-lane-reservation-release-barrier:v3\0",
            &norito::encode_canonical(self).expect("validated queue release barrier must encode"),
        ])
    }
}

/// Durable post-claim release state retained until FIFO restoration is safe.
///
/// A completion frame moves the exact live records here atomically. Keeping
/// the original durable ordinals makes a crash between that frame and FIFO
/// reinsertion restartable without changing global queue order.
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode)]
#[norito(deny_unknown_fields)]
pub(crate) struct LaneQueueReservationReleaseCompletionV5 {
    /// Reservation-journal schema version.
    pub(crate) version: u16,
    /// Exact prepared release barrier.
    pub(crate) barrier: LaneQueueReservationReleaseBarrierV3,
    /// Live records in the barrier's original order.
    pub(crate) ordered_records: Vec<LaneQueueReservationRecordV5>,
}

impl LaneQueueReservationReleaseCompletionV5 {
    fn validate(&self) -> Result<(), &'static str> {
        if self.version != LANE_QUEUE_RESERVATION_JOURNAL_VERSION {
            return Err("unsupported lane queue release completion version");
        }
        self.barrier.validate()?;
        if self.ordered_records.len() != self.barrier.ordered_keys.len() {
            return Err("lane queue release completion record count does not match its barrier");
        }
        for (record, key) in self.ordered_records.iter().zip(&self.barrier.ordered_keys) {
            record.validate()?;
            if record.key != *key {
                return Err("lane queue release completion order does not match its barrier");
            }
        }
        if self
            .ordered_records
            .windows(2)
            .any(|records| records[0].fifo_order.ordinal >= records[1].fifo_order.ordinal)
        {
            return Err("lane queue release completion records are not in original FIFO order");
        }
        Ok(())
    }
}

/// A transaction whose full queue ownership was durably transferred to one lane proposal slot.
#[derive(Clone)]
pub struct LaneReservedTransaction {
    key: LaneQueueReservationKeyV2,
    tx: Arc<CheckedTransaction<'static>>,
    routing_plan: RoutingPlan,
    encoded_len: usize,
    gas_cost: u64,
}

impl LaneReservedTransaction {
    /// Borrow the exact durable reservation identity.
    #[must_use]
    pub fn key(&self) -> &LaneQueueReservationKeyV2 {
        &self.key
    }

    /// Clone the accepted transaction owned by this reservation.
    #[must_use]
    pub fn clone_accepted(&self) -> AcceptedTransaction<'static> {
        self.tx.as_accepted().clone()
    }

    /// Return the exact full routing plan bound by the reservation.
    #[must_use]
    pub fn routing_plan(&self) -> &RoutingPlan {
        &self.routing_plan
    }

    /// Return the queue-retained encoded length used for block budgets.
    #[must_use]
    pub fn encoded_len(&self) -> usize {
        self.encoded_len
    }

    /// Return the proposal gas cost cached at admission.
    #[must_use]
    pub fn gas_cost(&self) -> u64 {
        self.gas_cost
    }
}

impl Deref for LaneReservedTransaction {
    type Target = CheckedTransaction<'static>;

    fn deref(&self) -> &Self::Target {
        &self.tx
    }
}

/// Result of one idempotent reservation retain/release/commit operation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LaneQueueReservationOutcome {
    /// The exact live reservation was retained without changing ownership.
    Retained,
    /// The exact live reservation was durably released or committed.
    Finalized,
    /// No exact live reservation existed; repeating the operation is harmless.
    AlreadyFinalized,
}

/// Summary returned after installing and replaying a reservation journal.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct LaneQueueReservationReplaySummary {
    /// Exact live reservations restored from durable frames.
    pub restored: usize,
    /// Restored reservations whose transaction payload has not been replayed into the queue yet.
    pub awaiting_transaction_replay: usize,
    /// Exact commit barriers retained until pending-plan tombstones become durable.
    pub commit_barriers: usize,
    /// Prepared ordered releases whose transactions remain lane-owned.
    pub release_barriers: usize,
    /// Completed releases retained until every transaction can be restored to FIFO.
    pub completed_releases: usize,
}

/// Reservation substrate failure.
#[derive(Debug, Error)]
pub enum LaneQueueReservationError {
    /// A durable reservation journal must be installed before lane selection.
    #[error("lane queue reservation journal is not installed")]
    JournalNotInstalled,
    /// A queue supports exactly one reservation journal installation per process lifetime.
    #[error("lane queue reservation journal is already installed")]
    JournalAlreadyInstalled,
    /// Journal replay cannot overlap ordinary queue selection or in-flight transaction guards.
    #[error(
        "lane queue reservation journal cannot be installed while queue selection is in flight"
    )]
    InflightSelection,
    /// Queue ownership is ambiguous after a failed durability boundary.
    #[error(
        "queue durability is faulted; transaction selection is disabled until restart recovery"
    )]
    DurabilityFault,
    /// Reservation identity is malformed: {0}.
    #[error("invalid lane queue reservation identity: {0}")]
    InvalidIdentity(String),
    /// The requested lane incarnation is stale or inactive.
    #[error("lane queue reservation requested a stale or inactive lane incarnation")]
    StaleLaneIncarnation,
    /// The requested lane/dataspace pair is not active at the proposal height.
    #[error("lane queue reservation requested an inactive lane/dataspace route")]
    InactiveRoute,
    /// A different exact identity already reserves transaction {hash}.
    #[error("conflicting live lane queue reservation for transaction {hash}")]
    Conflict {
        /// Signed transaction hash already owned by another exact reservation.
        hash: HashOf<iroha_data_model::transaction::SignedTransaction>,
    },
    /// A distinct ordered release already owns the same retirement or slot.
    #[error("conflicting lane queue release barrier for retirement {retirement_hash}")]
    ReleaseConflict {
        /// Digest of the requested exact Kura retirement.
        retirement_hash: Hash,
    },
    /// Reservation journal I/O or recovery failed.
    #[error("lane queue reservation journal failed: {0}")]
    Journal(#[from] std::io::Error),
}

#[derive(Default)]
struct LaneQueueReservationStore {
    journal: Option<LaneQueueReservationJournal>,
    live_by_hash: HashMap<SignedTxHash, LaneQueueReservationRecordV5>,
    commit_barriers: Vec<LaneQueueReservationKeyV2>,
    release_barriers: Vec<LaneQueueReservationReleaseBarrierV3>,
    completed_releases: Vec<LaneQueueReservationReleaseCompletionV5>,
    /// Durable reservation-owner identities whose transaction payload is not
    /// currently materialized in `Queue::txs`.
    missing_payload_hashes: HashSet<SignedTxHash>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PlanJournalDurability {
    Synced,
    StartupPending,
}

impl LaneQueueReservationStore {
    fn durable_owned_hashes(&self) -> impl Iterator<Item = SignedTxHash> + '_ {
        self.live_by_hash
            .keys()
            .copied()
            .chain(
                self.commit_barriers
                    .iter()
                    .map(|key| key.signed_transaction_hash),
            )
            .chain(self.release_barriers.iter().flat_map(|barrier| {
                barrier
                    .ordered_keys
                    .iter()
                    .map(|key| key.signed_transaction_hash)
            }))
            .chain(self.completed_releases.iter().flat_map(|completion| {
                completion
                    .ordered_records
                    .iter()
                    .map(|record| record.key.signed_transaction_hash)
            }))
    }

    fn live_hashes(&self) -> HashSet<SignedTxHash> {
        self.live_by_hash
            .keys()
            .copied()
            .chain(self.completed_releases.iter().flat_map(|completion| {
                completion
                    .ordered_records
                    .iter()
                    .map(|record| record.key.signed_transaction_hash)
            }))
            .collect()
    }

    fn exact(&self, key: &LaneQueueReservationKeyV2) -> bool {
        self.live_by_hash
            .get(&key.signed_transaction_hash)
            .is_some_and(|record| record.key == *key)
    }

    fn ensure_no_conflict(
        &self,
        key: &LaneQueueReservationKeyV2,
    ) -> Result<(), LaneQueueReservationError> {
        if self
            .live_by_hash
            .get(&key.signed_transaction_hash)
            .is_some_and(|record| record.key != *key)
        {
            return Err(LaneQueueReservationError::Conflict {
                hash: key.signed_transaction_hash,
            });
        }
        if self.commit_barriers.iter().any(|committed| {
            committed.signed_transaction_hash == key.signed_transaction_hash && committed != key
        }) || self.completed_releases.iter().any(|completion| {
            completion.ordered_records.iter().any(|record| {
                record.key.signed_transaction_hash == key.signed_transaction_hash
                    && record.key != *key
            })
        }) {
            return Err(LaneQueueReservationError::Conflict {
                hash: key.signed_transaction_hash,
            });
        }
        Ok(())
    }

    fn ensure_release_no_conflict(
        &self,
        requested: &LaneQueueReservationReleaseBarrierV3,
    ) -> Result<(), LaneQueueReservationError> {
        let same_slot = |existing: &LaneQueueReservationReleaseBarrierV3| {
            existing.chain_id_hash == requested.chain_id_hash
                && existing.epoch == requested.epoch
                && existing.lane_id == requested.lane_id
                && existing.dataspace_id == requested.dataspace_id
                && existing.lane_incarnation == requested.lane_incarnation
                && existing.proposal_height == requested.proposal_height
                && existing.lane_block_height == requested.lane_block_height
        };
        let overlaps = |existing: &LaneQueueReservationReleaseBarrierV3| {
            existing.ordered_keys.iter().any(|existing_key| {
                requested.ordered_keys.iter().any(|requested_key| {
                    requested_key.signed_transaction_hash == existing_key.signed_transaction_hash
                })
            })
        };
        for existing in self.release_barriers.iter().chain(
            self.completed_releases
                .iter()
                .map(|completion| &completion.barrier),
        ) {
            if existing == requested {
                continue;
            }
            if existing.retirement_hash == requested.retirement_hash
                || same_slot(existing)
                || overlaps(existing)
            {
                return Err(LaneQueueReservationError::ReleaseConflict {
                    retirement_hash: requested.retirement_hash,
                });
            }
        }
        if self.commit_barriers.iter().any(|committed| {
            requested.ordered_keys.iter().any(|requested_key| {
                requested_key.signed_transaction_hash == committed.signed_transaction_hash
            })
        }) {
            return Err(LaneQueueReservationError::ReleaseConflict {
                retirement_hash: requested.retirement_hash,
            });
        }
        Ok(())
    }

    fn ensure_not_release_prepared(
        &self,
        key: &LaneQueueReservationKeyV2,
    ) -> Result<(), LaneQueueReservationError> {
        if let Some(barrier) = self
            .release_barriers
            .iter()
            .find(|barrier| barrier.ordered_keys.iter().any(|prepared| prepared == key))
        {
            return Err(LaneQueueReservationError::ReleaseConflict {
                retirement_hash: barrier.retirement_hash,
            });
        }
        Ok(())
    }

    fn journal_mut(
        &mut self,
    ) -> Result<&mut LaneQueueReservationJournal, LaneQueueReservationError> {
        self.journal
            .as_mut()
            .ok_or(LaneQueueReservationError::JournalNotInstalled)
    }

    fn compact_if_needed(&mut self) -> std::io::Result<()> {
        let live: Vec<_> = self.live_by_hash.values().cloned().collect();
        let committed = self.commit_barriers.clone();
        let release_barriers = self.release_barriers.clone();
        let completed_releases = self.completed_releases.clone();
        let Some(journal) = self.journal.as_mut() else {
            return Ok(());
        };
        journal
            .compact_if_needed(&live, &committed, &release_barriers, &completed_releases)
            .map(|_| ())
    }
}

fn hash_is_zero(hash: Hash) -> bool {
    hash.as_ref().iter().all(|byte| *byte == 0)
}

/// Resolve every coordinator and participant leg in a full routing plan against active catalogs.
pub(crate) fn resolve_routing_plan_against_catalogs(
    plan: RoutingPlan,
    lane_catalog: &LaneCatalog,
    dataspace_catalog: &DataSpaceCatalog,
) -> Result<RoutingPlan, RoutingResolveError> {
    match plan {
        RoutingPlan::Single(leg) => {
            let route = resolve_routing_decision(leg.route, lane_catalog, dataspace_catalog)?;
            Ok(RoutingPlan::single(route))
        }
        RoutingPlan::NativeAmx(plan) => {
            let coordinator =
                resolve_routing_decision(plan.coordinator.route, lane_catalog, dataspace_catalog)?;
            let participants = plan
                .participants
                .into_iter()
                .map(|leg| {
                    resolve_routing_decision(leg.route, lane_catalog, dataspace_catalog)
                        .map(|route| RouteLeg::new(route, RouteLegRole::Participant))
                })
                .collect::<Result<Vec<_>, _>>()?;
            Ok(RoutingPlan::native_amx(coordinator, participants))
        }
    }
}

fn ensure_routing_plan_active_at_height(
    plan: &RoutingPlan,
    nexus: &Nexus,
    block_height: u64,
) -> Result<(), RoutingResolveError> {
    for leg in plan.legs() {
        let route = leg.route;
        if crate::state::nexus_active_lane_dataspace_at_height(route.lane_id, nexus, block_height)
            != Some(route.dataspace_id)
            && !route_uses_legacy_default_public_lane(route, nexus)
        {
            return Err(RoutingResolveError::InactiveLane {
                lane_id: route.lane_id,
                dataspace_id: route.dataspace_id,
            });
        }
    }
    Ok(())
}

fn route_uses_legacy_default_public_lane(route: RoutingDecision, nexus: &Nexus) -> bool {
    if nexus.enabled || route.lane_id != LaneId::SINGLE {
        return false;
    }
    let Some(default_lane) = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == LaneId::SINGLE)
    else {
        return false;
    };
    if default_lane.dataspace_id != DataSpaceId::UNIVERSAL
        || default_lane.metadata.contains_key(AUTOSCALE_META_MANAGED)
        || default_lane
            .metadata
            .contains_key(AUTOSCALE_META_CREATED_HEIGHT)
        || default_lane
            .metadata
            .contains_key(AUTOSCALE_META_DRAIN_STATE)
        || default_lane.metadata.contains_key(AUTOSCALE_META_COMMITTEE)
    {
        return false;
    }
    route.dataspace_id == DataSpaceId::UNIVERSAL
        || !nexus
            .lane_catalog
            .lanes()
            .iter()
            .any(|lane| lane.dataspace_id == route.dataspace_id)
}

fn resolve_routing_plan_against_nexus_at_height(
    plan: RoutingPlan,
    nexus: &Nexus,
    block_height: u64,
) -> Result<RoutingPlan, RoutingResolveError> {
    let plan =
        resolve_routing_plan_against_catalogs(plan, &nexus.lane_catalog, &nexus.dataspace_catalog)?;
    ensure_routing_plan_active_at_height(&plan, nexus, block_height)?;
    Ok(plan)
}

/// Resolve queue ownership against both the committed catalog and the next
/// proposal height.
///
/// The first check prevents a merely future-created lane from becoming
/// visible before its lifecycle carrier is committed. The second closes an
/// autoscale drain exactly after `close_global_height`: transactions accepted
/// while that height is the committed tip can only execute in the following
/// proposal and therefore must not acquire the closing route.
fn resolve_routing_plan_for_queue_admission(
    plan: RoutingPlan,
    nexus: &Nexus,
    committed_height: u64,
) -> Result<RoutingPlan, RoutingResolveError> {
    let plan = resolve_routing_plan_against_nexus_at_height(plan, nexus, committed_height)?;
    let Some(next_proposal_height) = committed_height.checked_add(1) else {
        let route = plan.coordinator_route();
        return Err(RoutingResolveError::InactiveLane {
            lane_id: route.lane_id,
            dataspace_id: route.dataspace_id,
        });
    };
    ensure_routing_plan_active_at_height(&plan, nexus, next_proposal_height)?;
    Ok(plan)
}

fn state_height_for_routing(state: &State) -> u64 {
    u64::try_from(state.committed_height()).unwrap_or(u64::MAX)
}

fn queue_plan_authoritative_peers_in_view_at_height(
    state_view: &impl StateReadOnly,
    route: RoutingDecision,
    proposal_height: u64,
) -> Vec<PeerId> {
    let validator_set =
        state_view.authoritative_lane_peer_ids_at_height(route.lane_id, proposal_height);
    if !validator_set.is_empty() {
        return validator_set;
    }

    if route_uses_legacy_default_public_lane(route, state_view.nexus()) {
        return state_view.commit_topology().to_vec();
    }
    Vec::new()
}

fn state_view_height_for_routing(state_view: &StateView<'_>) -> u64 {
    u64::try_from(state_view.height()).unwrap_or(u64::MAX)
}

fn nexus_with_route_catalogs(
    nexus: &Nexus,
    lane_catalog: &LaneCatalog,
    dataspace_catalog: &DataSpaceCatalog,
) -> Nexus {
    let mut nexus = nexus.clone();
    nexus.lane_catalog = lane_catalog.clone();
    nexus.dataspace_catalog = dataspace_catalog.clone();
    nexus.lane_config =
        iroha_config::parameters::actual::LaneConfig::from_catalog(&nexus.lane_catalog);
    nexus
}

/// Nexus-derived limits that influence queue telemetry and scheduling defaults.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LaneSchedulingLimits {
    /// TEU capacity per lane for telemetry snapshots.
    pub teu_capacity: u64,
    /// Starvation bound (slots) applied to dataspace metrics.
    pub starvation_bound_slots: u64,
}

impl LaneSchedulingLimits {
    /// Construct scheduling limits from explicit capacity and starvation configuration.
    pub const fn new(teu_capacity: u64, starvation_bound_slots: u64) -> Self {
        Self {
            teu_capacity,
            starvation_bound_slots,
        }
    }
}

/// Nexus-derived limits that influence queue telemetry and scheduling defaults.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct QueueLimits {
    fallback: LaneSchedulingLimits,
    per_lane: BTreeMap<LaneId, LaneSchedulingLimits>,
}

impl QueueLimits {
    /// Build limits using values from the runtime Nexus configuration.
    #[must_use]
    pub fn from_nexus(nexus: &Nexus) -> Self {
        let fallback = LaneSchedulingLimits::new(
            u64::from(nexus.fusion.exit_teu),
            u64::from(nexus.da.rotation.window_slots.get()),
        );
        let mut per_lane = BTreeMap::new();
        if nexus.enabled {
            for lane in nexus.lane_catalog.lanes() {
                let limits = Self::lane_limits_from_metadata(lane, fallback);
                per_lane.insert(lane.id, limits);
            }
        }
        Self { fallback, per_lane }
    }

    /// Derive lane-specific limits from metadata overrides or fall back to the global defaults.
    pub(crate) fn lane_limits_from_metadata(
        lane: &iroha_data_model::nexus::LaneConfig,
        fallback: LaneSchedulingLimits,
    ) -> LaneSchedulingLimits {
        let mut limits = fallback;
        if let Some(raw) = lane.metadata.get("scheduler.teu_capacity") {
            match raw.trim().parse::<u64>() {
                Ok(value) => limits.teu_capacity = value,
                Err(err) => warn!(
                    lane = %lane.alias,
                    value = raw,
                    %err,
                    "invalid scheduler.teu_capacity metadata; using fallback value"
                ),
            }
        }
        if let Some(raw) = lane.metadata.get("scheduler.starvation_bound_slots") {
            match raw.trim().parse::<u64>() {
                Ok(value) => limits.starvation_bound_slots = value,
                Err(err) => warn!(
                    lane = %lane.alias,
                    value = raw,
                    %err,
                    "invalid scheduler.starvation_bound_slots metadata; using fallback value"
                ),
            }
        }
        limits
    }

    /// Return the scheduling limits associated with `lane`, falling back to the global defaults.
    #[must_use]
    pub fn for_lane(&self, lane: LaneId) -> LaneSchedulingLimits {
        self.per_lane.get(&lane).copied().unwrap_or(self.fallback)
    }
}

impl Default for QueueLimits {
    fn default() -> Self {
        Self::from_nexus(&Nexus::default())
    }
}

